import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
export const countryPalettes={USA:['#214b91','#f9fafb','#df343e'],UK:['#1e4381','#ffffff','#d32d3a'],Mexico:['#21805c','#ffffff','#c9323d'],Brazil:['#169e64','#ffce32','#2454a1'],Italy:['#198559','#f8faf7','#db303c'],France:['#27499b','#fff','#e03844'],Japan:['#e33a45','#fff','#e33a45'],China:['#e33b34','#ffce37','#e33b34'],Spain:['#d32f37','#f8c535','#d32f37'],Australia:['#23477e','#ffffff','#d83d47'],Canada:['#dd3640','#ffffff','#dd3640'],Monaco:['#da3544','#ffffff'],Austria:['#d63c46','#ffffff','#d63c46'],Belgium:['#272c31','#ffd138','#da3943'],Hungary:['#d23943','#ffffff','#3e8260'],Netherlands:['#d24343','#ffffff','#2b508d'],Singapore:['#dc3744','#ffffff'],UAE:['#1b8c5c','#ffffff','#cf3541'],Qatar:['#8f2947','#ffffff'],Azerbaijan:['#4394c8','#d63546','#29845e'],Bahrain:['#db3843','#fff'],Malaysia:['#e34048','#fff','#274983'],Saudi_Arabia:['#258358','#fff'],'Saudi Arabia':['#258358','#fff']};
export function paletteFor(country){return countryPalettes[country]||['#e03941','#ffffff','#7f8991']}
export class CircuitViewer {
  constructor(container,feature,country,fallback){
    this.container=container;this.disposed=false;
    try {
      if(!feature)throw new Error('Track geometry is unavailable for this circuit.');
      const renderer=this.renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});
      renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0xffffff,0);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
      renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;
      container.replaceChildren(renderer.domElement);renderer.domElement.setAttribute('aria-label',`Interactive 3D circuit model: ${country}. Drag to orbit, scroll to zoom. Use the view buttons for top and isometric views.`);renderer.domElement.setAttribute('role','img');renderer.domElement.tabIndex=0;
      this.scene=new THREE.Scene();this.camera=new THREE.PerspectiveCamera(32,1,.1,200);this.camera.position.set(10,20,15);
      const controls=this.controls=new OrbitControls(this.camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.08;controls.enablePan=false;controls.minDistance=10;controls.maxDistance=50;controls.minPolarAngle=.05;controls.maxPolarAngle=Math.PI/2.1;controls.target.set(0,0,0);controls.enableZoom=false; // Wheel scroll remains page scroll; zoom buttons are explicit.
      renderer.domElement.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){this.camera.position.applyAxisAngle(new THREE.Vector3(0,1,0),e.key==='ArrowLeft'?.12:-.12);e.preventDefault()}else if(e.key==='+'||e.key==='='){this.zoom(.85);e.preventDefault()}else if(e.key==='-'){this.zoom(1.15);e.preventDefault()}});
      this.scene.add(new THREE.AmbientLight(0xffffff,1.7));const sun=new THREE.DirectionalLight(0xffffff,3.5);sun.position.set(-10,20,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-15,right:15,top:15,bottom:-15});sun.shadow.normalBias=.03;this.scene.add(sun);
      const coords=feature.geometry.coordinates;const cos=Math.cos(coords[0][1]*Math.PI/180);let points=coords.map(p=>new THREE.Vector3(p[0]*cos,0,-p[1]));const box=new THREE.Box3().setFromPoints(points),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3());const scale=15/Math.max(size.x,size.z);points=points.map(p=>p.sub(center).multiplyScalar(scale));if(points[0].distanceTo(points.at(-1))<.01)points.pop();
      // Geographic polyline with modest smoothing; no fabricated elevation profile.
      const curve=new THREE.CatmullRomCurve3(points,true,'centripetal',.1),samples=curve.getSpacedPoints(1100);
      const palette=paletteFor(country);const group=new THREE.Group();this.scene.add(group);
      const ribbon=(inner,outer,y,material)=>{const vertices=[],indices=[];samples.forEach((p,i)=>{const prev=samples[(i+samples.length-2)%(samples.length-1)],next=samples[(i+1)%(samples.length-1)];const tangent=next.clone().sub(prev).normalize(),normal=new THREE.Vector3(-tangent.z,0,tangent.x);for(const width of [inner,outer])vertices.push(p.x+normal.x*width,y,p.z+normal.z*width);if(i<samples.length-1){const a=i*2;indices.push(a,a+1,a+2,a+1,a+3,a+2)}});const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));g.setIndex(indices);g.computeVertexNormals();const mesh=new THREE.Mesh(g,material);mesh.receiveShadow=true;mesh.castShadow=true;group.add(mesh);return mesh;};
      const roadMat=new THREE.MeshStandardMaterial({color:'#30343a',roughness:.85,side:THREE.DoubleSide});const vergeMat=new THREE.MeshStandardMaterial({color:'#e4e9e2',roughness:1,side:THREE.DoubleSide});
      ribbon(-.34,.34,.045,vergeMat);ribbon(-.20,.20,.13,roadMat);
      // Give the geographic path real mesh depth, rather than a CSS perspective image.
      const borderCurve=offset=>new THREE.CatmullRomCurve3(samples.slice(0,-1).filter((_,i)=>i%3===0).map((p,i,arr)=>{const next=arr[(i+1)%arr.length],normal=new THREE.Vector3(-(next.z-p.z),0,next.x-p.x).normalize();return new THREE.Vector3(p.x+normal.x*offset,.09,p.z+normal.z*offset)}),true);
      const edgeMat=new THREE.MeshStandardMaterial({color:'#a8adb1',roughness:.7});for(const side of [-1,1]){const edge=new THREE.Mesh(new THREE.TubeGeometry(borderCurve(side*.2),900,.035,5,true),edgeMat);group.add(edge);}
      const segmentColors=[];for(let i=0;i<samples.length-1;i++){const p=samples[i],q=samples[i+1],normal=q.clone().sub(p).normalize();normal.set(-normal.z,0,normal.x);for(const side of [-1,1]){const a=p.clone().addScaledVector(normal,.23*side),b=q.clone().addScaledVector(normal,.23*side);segmentColors.push({a,b,c:palette[Math.floor(i/(samples.length-1)*palette.length)]});}}
      const railPositions=[],railColors=[];for(const {a,b,c} of segmentColors){railPositions.push(a.x,.16,a.z,b.x,.16,b.z);const col=new THREE.Color(c);railColors.push(col.r,col.g,col.b,col.r,col.g,col.b);}const rails=new THREE.BufferGeometry();rails.setAttribute('position',new THREE.Float32BufferAttribute(railPositions,3));rails.setAttribute('color',new THREE.Float32BufferAttribute(railColors,3));group.add(new THREE.LineSegments(rails,new THREE.LineBasicMaterial({vertexColors:true})));
      // Country-color surface edging: equal sections are styling, not timing sectors.
      const accents=ribbon(.205,.27,.145,new THREE.MeshStandardMaterial({vertexColors:true,side:THREE.DoubleSide,roughness:.6}));const col=[];samples.forEach((_,i)=>{const c=new THREE.Color(palette[Math.min(palette.length-1,Math.floor(i/(samples.length-1)*palette.length))]);for(let j=0;j<2;j++)col.push(c.r,c.g,c.b)});accents.geometry.setAttribute('color',new THREE.Float32BufferAttribute(col,3));
      const floor=new THREE.Mesh(new THREE.PlaneGeometry(90,90),new THREE.ShadowMaterial({opacity:.09}));floor.rotation.x=-Math.PI/2;floor.position.y=-.04;floor.receiveShadow=true;this.scene.add(floor);
      const grid=new THREE.GridHelper(32,32,0xe7e8ea,0xededee);grid.material.transparent=true;grid.material.opacity=.48;grid.position.y=-.03;this.scene.add(grid);
      const first=samples[0],second=samples[1];const start=new THREE.Group();for(let a=0;a<2;a++)for(let b=0;b<6;b++){const m=new THREE.Mesh(new THREE.BoxGeometry(.06,.014,.064),new THREE.MeshStandardMaterial({color:(a+b)%2?'#f8f8f7':'#33363a'}));m.position.set((a-.5)*.06,.17,(b-2.5)*.064);start.add(m)}start.position.set(first.x,0,first.z);start.rotation.y=Math.atan2(second.x-first.x,second.z-first.z);group.add(start);
      const beacon=new THREE.Mesh(new THREE.CylinderGeometry(.04,.04,.7,10),new THREE.MeshStandardMaterial({color:palette[0]}));beacon.position.set(first.x,.48,first.z+.4);group.add(beacon);const flag=new THREE.Mesh(new THREE.BoxGeometry(.46,.27,.018),new THREE.MeshStandardMaterial({color:palette[0]}));flag.position.set(first.x+.23,.8,first.z+.4);group.add(flag);
      this.resizeObserver=new ResizeObserver(()=>this.resize());this.resizeObserver.observe(container);this.resize();
      const tick=()=>{if(this.disposed)return;this.frame=requestAnimationFrame(tick);if(container.clientWidth&&container.clientHeight&&container.getClientRects().length){controls.update();renderer.render(this.scene,this.camera)}};tick();
    } catch(error){this.dispose();container.innerHTML=fallback||`<div class="empty">${String(error.message)}</div>`;container.dataset.fallback='true';}
  }
  resize(){const w=this.container.clientWidth,h=this.container.clientHeight;if(w&&h){this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();}}
  setView(top=false){if(!this.camera||!this.controls)return;this.camera.position.set(...(top?[0,32,.01]:[10,20,15]));this.controls.update();}
  zoom(factor){if(!this.camera||!this.controls)return;const p=this.camera.position.clone().sub(this.controls.target).multiplyScalar(factor);p.clampLength(10,50);this.camera.position.copy(this.controls.target).add(p);this.controls.update();}
  dispose(){this.disposed=true;cancelAnimationFrame(this.frame);this.resizeObserver?.disconnect();this.controls?.dispose();if(this.scene){const geometries=new Set(),materials=new Set();this.scene.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>materials.add(m))});geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose())}this.renderer?.dispose();}
}
